// Read the form answers (or the Config defaults on a manual run), check them and plan
// the search. Nothing in this node spends credits.
const cfg = $input.first().json;
const fromForm = cfg['Hashtag'] !== undefined;
const num = (v, d) => (v === '' || v === null || v === undefined || !Number.isFinite(Number(v)) ? d : Number(v));
const clean = t => String(t ?? '').normalize('NFC').trim().replace(/^#+/, '').replace(/\s+/g, '').toLowerCase();

const hashtag = clean(fromForm ? cfg['Hashtag'] : cfg.defaultHashtag);
const maxSample = Math.min(Math.max(Math.floor(num(cfg.maxSampleSize, 100)), 10), 200);
const requested = Math.floor(num(fromForm ? cfg['Sample size'] : cfg.defaultSampleSize, 30));

const problems = [];
if (!hashtag) problems.push('Enter a hashtag, for example coffee.');
else if (!/^[\p{L}\p{N}_]+$/u.test(hashtag)) problems.push(`"${hashtag}" is not a valid Instagram hashtag. Use letters, numbers and underscores only.`);
else if (hashtag.length > 100) problems.push('The hashtag is too long (100 characters at most).');
if (requested < 1) problems.push('The sample size must be at least 1.');

if (problems.length) {
  // A manual run has no form page to show the problem on, so stop with a clear message instead.
  if (!fromForm) throw new Error(problems.join(' ') + ' Fix the defaults in the "Config" node.');
  return [{ json: { valid: false, fromForm, hashtag, problems } }];
}

// Always the Instagram "posts" feed (the API's default hashtag feed).
const sampleSize = Math.min(requested, maxSample);
const extraExclude = fromForm ? String(cfg['Exclude hashtags'] ?? '') : '';
return [{
  json: { valid: true, fromForm, hashtag, feedType: 'posts', feeds: ['posts'], limit: sampleSize, sampleSize, sampleCapped: requested > maxSample, extraExclude },
}];

// Count search attempts. The first attempt comes from "Request valid?",
// later attempts come back from "Back off before retry".
const { _kind, lastError, waitSeconds, ...job } = $input.first().json;
return [{ json: { ...job, attempt: (Number(job.attempt) || 0) + 1 } }];

// Runs once per search attempt. Passes posts on and turns a failure into either
// a retry request (temporary errors only) or an error marker.
// Always returns at least one item, so the analysis still runs and can explain an empty result.
const cfg = $('Set Default Parameters').first().json;
const req = $('Prepare Search Attempt').first().json;
const maxRetries = Math.min(Math.max(Math.floor(Number(cfg.maxRetries) || 0), 0), 3);
const baseWait = Math.max(Number(cfg.retryBaseSeconds) || 5, 1);

const posts = [];
let failure = null;
for (const { json: j } of $input.all()) {
  // Our fields go last so a new API field can never overwrite them.
  if (j && j.url) posts.push({ json: { ...j, _kind: 'post', feedType: req.feedType } });
  else if (j && j.error !== undefined && j.error !== null) failure = typeof j.error === 'string' ? j.error : JSON.stringify(j.error);
}
if (failure === null) {
  return posts.length ? posts : [{ json: { _kind: 'empty', feedType: req.feedType } }];
}

// The node reports errors as text, for example "Request failed with status code 503".
const match = failure.match(/\b([45]\d\d)\b/);
const status = match ? Number(match[1]) : null;
const temporary = status !== null ? status >= 500
  : /timeout|timed out|ECONNRESET|ECONNREFUSED|ETIMEDOUT|EAI_AGAIN|socket hang up/i.test(failure);

if (temporary && req.attempt <= maxRetries) {
  // Exponential backoff: 5 s, 10 s, 20 s with the default base. Failed searches cost no credit.
  return [{ json: { ...req, _kind: 'retry', lastError: failure.slice(0, 200), waitSeconds: baseWait * 2 ** (req.attempt - 1) } }];
}

// 4xx errors are never retried: the same request would fail again.
const advice = {
  400: 'RecentReborn rejected the request. Check the hashtag spelling.',
  401: 'The API key is missing, revoked or wrong. Update the RecentReborn credential in n8n.',
  403: 'Your RecentReborn plan does not include API access.',
  429: 'The daily search quota is used up, or more than 20 requests were sent in one minute. Try again after the quota resets.',
}[status] || (temporary
  ? `RecentReborn or Instagram had a temporary problem (tried ${req.attempt} times). Try again in a few minutes.`
  : 'Unexpected error. Open this execution in n8n to see the details.');

return [{ json: { _kind: 'error', feedType: req.feedType, status, attempts: req.attempt, message: failure.slice(0, 300), advice } }];

// Count which hashtags appear together with the searched hashtag.
// Ranking uses unique accounts first, so one account posting many times cannot dominate the table.
const cfg = $('Set Default Parameters').first().json;
const req = $('Validate Request Data').first().json;
const num = (v, d) => (v === '' || v === null || v === undefined || !Number.isFinite(Number(v)) ? d : Number(v));
const norm = t => String(t ?? '').normalize('NFC').trim().replace(/^#+/, '').toLowerCase();
const list = v => String(v ?? '').split(/[,\s]+/).map(norm).filter(Boolean);
const round = (v, d = 1) => Math.round(v * 10 ** d) / 10 ** d;
const ASSUMED_PAGE_SIZE = 25; // inferred from the API docs example, only used for the credit estimate

const seed = req.hashtag;
const maxTagsPerPost = Math.max(1, num(cfg.maxHashtagsPerPost, 30));
const minAccounts = Math.max(1, Math.floor(num(cfg.minAccountsPerHashtag, 2)));
const tableRows = Math.max(1, Math.floor(num(cfg.tableRows, 30)));
const pairRows = Math.max(0, Math.floor(num(cfg.pairRows, 10)));
const copyCount = Math.max(1, Math.floor(num(cfg.copyTagCount, 15)));

// Never shown: the searched hashtag, its plural or singular form, and the exclude lists.
const exclude = new Set([seed, ...list(cfg.alwaysExclude), ...list(req.extraExclude)]);
if (cfg.excludeSeedVariants !== false) {
  exclude.add(seed + 's');
  exclude.add(seed + 'es');
  if (seed.endsWith('s')) exclude.add(seed.slice(0, -1));
}

// 1. Collect usable posts, each post once.
// Instagram can return one post as /p/CODE and /reel/CODE, or with tracking parameters,
// so the shortcode (not the full URL) is the dedupe key.
const postKey = u => {
  const m = String(u ?? '').match(/instagram\.com\/(?:[^/?#]+\/)?(?:p|reels?|tv)\/([A-Za-z0-9_-]+)/i);
  return m ? 'ig:' + m[1] : String(u ?? '').split(/[?#]/)[0].replace(/\/+$/, '').toLowerCase();
};
const dropReposts = cfg.dropReposts !== false;
const stats = { fetched: 0, duplicates: 0, reposts: 0, stuffed: 0, noOtherTags: 0 };
const perFeed = {};
const errors = [];
const byKey = new Map(); // every unique post, for the post list on the page
const seenCaptions = new Set();
const posts = [];
for (const { json: p } of $input.all()) {
  if (p._kind === 'error') { errors.push(p); continue; }
  if (p._kind !== 'post') continue;
  stats.fetched++;
  perFeed[p.feedType] = (perFeed[p.feedType] || 0) + 1;
  const key = postKey(p.url);
  if (byKey.has(key)) { // same post returned twice, for example on two pages or as a /reel/ link
    const prev = byKey.get(key);
    if (!prev.feeds.includes(p.feedType)) prev.feeds.push(p.feedType);
    stats.duplicates++;
    continue;
  }
  const account = String(p.author_id ?? p.author ?? 'unknown');
  const caption = String(p.caption ?? '').replace(/\s+/g, ' ').trim();
  // The same account posting the same caption again (reposted promos) counts once.
  const captionKey = account + '|' + caption.toLowerCase();
  if (dropReposts && caption.length >= 20 && seenCaptions.has(captionKey)) { stats.reposts++; continue; }
  seenCaptions.add(captionKey);
  // Use the hashtags field plus any #tag in the caption that the field does not list.
  const fromCaption = caption.match(/#[\p{L}\p{N}_]+/gu) || [];
  const allTags = new Set([...(Array.isArray(p.hashtags) ? p.hashtags : []), ...fromCaption].map(norm).filter(Boolean));
  const stuffed = allTags.size > maxTagsPerPost;
  const url = String(p.url ?? '').split(/[?#]/)[0].replace(/\/+$/, '');
  const postedAt = Date.parse(p.posted_at ?? '');
  const likes = typeof p.likes === 'number' ? p.likes : null; // null when likes are hidden or missing
  byKey.set(key, {
    url,
    postedAt: Number.isNaN(postedAt) ? null : new Date(postedAt).toISOString(),
    author: p.author ?? null,
    feeds: [p.feedType],
    isVideo: p.is_video === true,
    likes,
    hashtagCount: allTags.size,
    tags: [...allTags].filter(t => t !== seed),
    caption: caption.length > 220 ? caption.slice(0, 217) + '...' : caption,
    status: stuffed ? 'stuffed' : 'analysed',
  });
  if (stuffed) { stats.stuffed++; continue; }
  const tags = [...allTags].filter(t => !exclude.has(t));
  if (tags.length === 0) stats.noOtherTags++;
  posts.push({ account, url, likes, postedAt, tagCount: allTags.size, tags });
}
// Every unique post, newest first (posts without a date go last).
const postList = [...byKey.values()].sort((a, b) => (b.postedAt ?? '').localeCompare(a.postedAt ?? ''));

// 2. Sample-level numbers.
const n = posts.length;
const postsByAccount = new Map();
for (const p of posts) postsByAccount.set(p.account, (postsByAccount.get(p.account) || 0) + 1);
const uniqueAccounts = postsByAccount.size;
const topAccountPosts = Math.max(0, ...postsByAccount.values());
const liked = posts.filter(p => p.likes !== null);
const sampleAvgLikes = liked.length ? liked.reduce((a, p) => a + p.likes, 0) / liked.length : null;
const times = posts.map(p => p.postedAt).filter(t => !Number.isNaN(t)).sort((a, b) => a - b);
const spanHours = times.length > 1 ? (times[times.length - 1] - times[0]) / 3600000 : null;
const tagCounts = posts.map(p => p.tagCount).sort((a, b) => a - b);
const medianTags = tagCounts.length ? tagCounts[Math.floor(tagCounts.length / 2)] : 0;

// 3. One entry per co-used hashtag.
const byTag = new Map();
for (const p of posts) {
  for (const t of p.tags) {
    let s = byTag.get(t);
    if (!s) byTag.set(t, (s = { posts: 0, accounts: new Map(), likeSum: 0, likeN: 0, best: null }));
    s.posts++;
    s.accounts.set(p.account, (s.accounts.get(p.account) || 0) + 1);
    if (p.likes !== null) { s.likeSum += p.likes; s.likeN++; }
    if (!s.best || (p.likes ?? -1) > (s.best.likes ?? -1)) s.best = p;
  }
}
const rows = [...byTag.entries()]
  .filter(([, s]) => s.accounts.size >= minAccounts)
  .map(([tag, s]) => {
    const avgLikes = s.likeN ? s.likeSum / s.likeN : null;
    return {
      hashtag: tag,
      accounts: s.accounts.size,
      posts: s.posts,
      sharePct: round((100 * s.posts) / n),
      avgLikes: avgLikes === null ? null : Math.round(avgLikes),
      // 1.0 = as many likes as the average post in the sample. Needs at least 2 posts with likes.
      engagementIndex: avgLikes !== null && s.likeN >= 2 && sampleAvgLikes ? round(avgLikes / sampleAvgLikes, 2) : null,
      // One account made more than half of the uses, for example a brand repeating its own tag set.
      concentrated: s.posts >= 3 && Math.max(...s.accounts.values()) / s.posts > 0.5,
      containsSearchTerm: tag.includes(seed),
      examplePost: s.best.url,
    };
  })
  .sort((a, b) => b.accounts - a.accounts || b.posts - a.posts || (b.avgLikes ?? -1) - (a.avgLikes ?? -1) || a.hashtag.localeCompare(b.hashtag))
  .slice(0, tableRows)
  .map((r, i) => ({ rank: i + 1, ...r }));

// 4. Pairs of listed hashtags that appear in the same post, counted by accounts.
const listed = new Set(rows.map(r => r.hashtag));
const pairMap = new Map();
for (const p of posts) {
  const t = p.tags.filter(x => listed.has(x)).sort();
  for (let i = 0; i < t.length; i++) {
    for (let j = i + 1; j < t.length; j++) {
      const key = t[i] + '|' + t[j];
      let s = pairMap.get(key);
      if (!s) pairMap.set(key, (s = { a: t[i], b: t[j], posts: 0, accounts: new Set() }));
      s.posts++;
      s.accounts.add(p.account);
    }
  }
}
// All qualifying pairs feed the network graph (capped), the top ones are listed as a table.
const edges = [...pairMap.values()]
  .filter(s => s.accounts.size >= minAccounts)
  .map(s => ({ pair: [s.a, s.b], accounts: s.accounts.size, posts: s.posts }))
  .sort((a, b) => b.accounts - a.accounts || b.posts - a.posts)
  .slice(0, 300);
const pairs = edges.slice(0, pairRows);

// 5. Warnings and run summary.
const warnings = [];
const smallSample = Math.max(1, num(cfg.smallSampleWarning, 20));
const maxAccountShare = num(cfg.maxAccountSharePct, 30);
if (req.sampleCapped) warnings.push(`The sample was capped at ${req.sampleSize} posts by maxSampleSize in Config.`);
if (n > 0 && n < smallSample) warnings.push(`Only ${n} usable posts. Treat the ranking as indicative.`);
if (n > 0 && (100 * topAccountPosts) / n > maxAccountShare) {
  warnings.push(`One account made ${topAccountPosts} of ${n} posts (${round((100 * topAccountPosts) / n)}%). The ranking counts it once per hashtag, but shares and averages are skewed.`);
}
if (stats.reposts > 0) warnings.push(`${stats.reposts} repeated post(s) (same account, same caption) were counted once.`);
if (stats.stuffed > 0) warnings.push(`${stats.stuffed} post(s) with more than ${maxTagsPerPost} hashtags were skipped as hashtag stuffing.`);
if (!errors.length && stats.fetched < req.sampleSize * 0.8) {
  warnings.push(`RecentReborn returned ${stats.fetched} of ${req.sampleSize} requested posts. The hashtag may have little recent activity.`);
}
for (const e of errors) warnings.push(`The ${e.feedType} search failed${e.status ? ` (HTTP ${e.status})` : ''}: ${e.advice}`);

const failedFeeds = new Set(errors.map(e => e.feedType));
const estimatedCredits = req.feeds
  .filter(f => !failedFeeds.has(f))
  .reduce((a, f) => a + Math.max(1, Math.ceil((perFeed[f] || 0) / ASSUMED_PAGE_SIZE)), 0);
const outcome = failedFeeds.size === req.feeds.length ? 'failed' : n === 0 ? 'no_posts' : rows.length === 0 ? 'no_cohashtags' : 'results';

return [{
  json: {
    fromForm: req.fromForm,
    outcome,
    summary: {
      hashtag: seed,
      requestedPosts: req.sampleSize,
      feeds: req.feeds,
      perFeed,
      fetched: stats.fetched,
      duplicates: stats.duplicates,
      reposts: stats.reposts,
      uniquePosts: postList.length,
      stuffed: stats.stuffed,
      analysedPosts: n,
      postsWithoutOtherTags: stats.noOtherTags,
      uniqueAccounts,
      distinctCoHashtags: byTag.size,
      shownHashtags: rows.length,
      minAccounts,
      medianHashtagsPerPost: medianTags,
      avgLikes: sampleAvgLikes === null ? null : Math.round(sampleAvgLikes),
      postsWithLikes: liked.length,
      newestPostAt: times.length ? new Date(times[times.length - 1]).toISOString() : null,
      oldestPostAt: times.length ? new Date(times[0]).toISOString() : null,
      spanHours: spanHours === null ? null : round(spanHours),
      postsPerHour: spanHours ? round(n / spanHours) : null,
      estimatedCredits,
      finishedAt: new Date().toISOString(),
    },
    warnings,
    errors,
    rows,
    pairs,
    edges,
    posts: postList,
    copyTags: rows.slice(0, copyCount).map(r => '#' + r.hashtag).join(' '),
  },
}];

// Build the results page for the form completion screen.
// n8n inserts this HTML into the <body> of its own page, so the output is a fragment:
// all styles are scoped under .hr-app and the script runs inside its own function.
// The table is plain HTML and works without JavaScript. The script adds sorting, filtering,
// a hashtag set to copy, CSV download and the network graph.
// To deliver the results somewhere else, replace this node and the two after it.
const d = $input.first().json;
const s = d.summary;
const cfg = $('Set Default Parameters').first().json;
const graphNodes = Math.max(0, Math.floor(Number(cfg.graphNodes) || 0));
const copyCount = Math.max(1, Math.floor(Number(cfg.copyTagCount) || 15));

const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const fmt = v => (v === null || v === undefined ? 'n/a' : Number(v).toLocaleString('en-US'));
const isUrl = u => /^https:\/\//i.test(String(u ?? ''));
const tagUrl = t => 'https://www.instagram.com/explore/tags/' + encodeURIComponent(t) + '/';
const ago = iso => {
  if (!iso) return 'n/a';
  const m = Math.max(0, Math.round((Date.now() - Date.parse(iso)) / 60000));
  return m < 1 ? 'just now' : m < 60 ? `${m} min ago` : m < 2880 ? `${Math.round(m / 60)} h ago` : `${Math.round(m / 1440)} days ago`;
};
const span = h => (h === null ? 'n/a' : h < 1 ? `${Math.round(h * 60)} min` : h < 48 ? `${Math.round(h * 10) / 10} h` : `${Math.round(h / 24)} days`);
const csvCell = v => (/[",\n]/.test(String(v ?? '')) ? `"${String(v).replace(/"/g, '""')}"` : String(v ?? ''));
const eiClass = v => (v === null ? 'na' : v >= 1.2 ? 'hi' : v <= 0.8 ? 'lo' : 'mid');
// JSON inside <script> must not contain "</script>" or line separators.
const safeJson = o => JSON.stringify(o).replace(/</g, '\\u003c').replace(/\u2028/g, '\\u2028').replace(/\u2029/g, '\\u2029');
const feedLabel = 'posts';
// Branding follows recentreborn.com: Poppins, purple #9d7ce3, white cards, black primary buttons.
const LOGO_URL = 'https://recentreborn.com/logo.png';
const SITE_URL = 'https://recentreborn.com/';
const fonts = '<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>'
  + '<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&family=Geist+Mono:wght@400;500&display=swap">';
const panelHead = (label, title) => `<div><div class="hr-label">${label}</div><h2>${title}</h2></div>`;
const searchBox = (id, placeholder) => `<label class="hr-search"><span aria-hidden="true">#</span><input type="search" id="${id}" placeholder="${placeholder}" aria-label="${placeholder}"></label>`;

const css = `
body{background:radial-gradient(1100px 520px at 12% -8%,rgba(157,124,227,.20),transparent 62%),radial-gradient(900px 460px at 92% -4%,rgba(244,182,214,.24),transparent 60%),#fbfaff;background-repeat:no-repeat}
