.hr-posts td{display:block;padding:0;border:0}.hr-posts .c-posted{grid-column:1;grid-row:1}.hr-posts .c-link{grid-column:2;grid-row:1;text-align:right}
.hr-posts .c-account{grid-column:1;grid-row:2}.hr-posts .c-likes{grid-column:2;grid-row:2;text-align:right}.hr-unit{display:inline}
.hr-posts .c-tags,.hr-posts .c-cap{grid-column:1/-1}.hr-posts .c-posted br{display:none}.hr-posts .c-posted small{margin-left:6px}}
@media (max-width:640px){.hr-app{padding:0 14px}.hr-hero{padding:30px 0 18px}.hr-live{display:none}.hr-panel{padding:16px;border-radius:18px}.hr-search{flex:1 1 100%}.hr-app .hr-search input{min-width:0;width:100%}}
@media print{body{background:#fff}.hr-tools,.hr-setbar,.hr-col-pick{display:none!important}.hr-panel,.hr-card{break-inside:avoid;box-shadow:none}}`;

const card = (value, label) => `<div class="hr-card"><span>${esc(label)}</span><b>${esc(value)}</b></div>`;
const cards = `<section class="hr-cards">${[
  card(fmt(s.analysedPosts), `posts analysed of ${fmt(s.fetched)}`),
  card(fmt(s.uniqueAccounts), 'accounts'),
  card(fmt(s.distinctCoHashtags), 'co-used hashtags'),
  card(fmt(s.medianHashtagsPerPost), 'hashtags per post (median)'),
  card(span(s.spanHours), 'time covered'),
  card(s.postsPerHour === null ? 'n/a' : `${fmt(s.postsPerHour)}/h`, 'posting rate'),
  card(ago(s.newestPostAt), 'newest post'),
].join('')}</section>`;
const warnings = d.warnings.length ? `<div class="hr-msg"><ul>${d.warnings.map(w => `<li>${esc(w)}</li>`).join('')}</ul></div>` : '';
// Every unique post with its link, newest first. The script can flip the order and filter it.
const listedTags = new Set((d.rows || []).map(r => r.hashtag));
const postRows = (d.posts || []).map(p => {
  const shown = p.tags.slice(0, 10);
  const chips = shown.map(t => `<span class="hr-ptag${listedTags.has(t) ? ' top' : ''}">#${esc(t)}</span>`).join('')
    + (p.tags.length > shown.length ? `<span class="hr-ptag more">+${p.tags.length - shown.length}</span>` : '');
  const account = p.author ? (/^[A-Za-z0-9._]{1,30}$/.test(p.author)
    ? `<a href="https://www.instagram.com/${esc(p.author)}/" target="_blank" rel="noopener">@${esc(p.author)}</a>` : esc(p.author)) : '<span class="hr-muted">unknown</span>';
  const skipped = p.status === 'stuffed' ? `<span class="hr-badge w" title="Not counted in the analysis">skipped: ${p.hashtagCount} hashtags</span> ` : '';
  return `<tr class="${p.status === 'stuffed' ? 'hr-skipped' : ''}" data-time="${p.postedAt ? Date.parse(p.postedAt) : ''}" data-tags=" ${esc(p.tags.join(' '))} " data-text="${esc(((p.author || '') + ' ' + p.caption).toLowerCase())}">`
    + `<td class="c-posted">${p.postedAt ? `<time datetime="${esc(p.postedAt)}">${esc(p.postedAt.slice(0, 16).replace('T', ' '))} UTC</time><br><small class="hr-muted">${esc(ago(p.postedAt))}</small>` : '<span class="hr-muted">unknown</span>'}</td>`
    + `<td class="c-account">${account}</td><td class="n c-likes">${fmt(p.likes)}<span class="hr-unit"> likes</span></td>`
    + `<td class="hr-ptags c-tags">${skipped}${chips || '<span class="hr-muted">none</span>'}</td>`
    + `<td class="hr-cap c-cap">${esc(p.caption) || '<span class="hr-muted">no caption</span>'}</td>`
    + `<td class="c-link">${isUrl(p.url) ? `<a href="${esc(p.url)}" target="_blank" rel="noopener">Open&nbsp;&#8599;</a>` : ''}</td></tr>`;
}).join('');
const postsPanel = postRows ? `<section class="hr-panel" id="hr-posts"><div class="hr-panel-head">${panelHead('04. Posts', `All posts (<span id="hr-post-count">${fmt(d.posts.length)}</span>)`)}
<div class="hr-tools js-only">${searchBox('hr-post-filter', 'Hashtag, account or text')}
<select id="hr-post-order" aria-label="Order"><option value="desc">Newest first</option><option value="asc">Oldest first</option></select></div></div>
<p class="hr-note" style="margin:-6px 0 10px!important">Every post in the sample, each listed once. Duplicates (the same post returned twice) and repeated posts (same account, same caption) are removed. Highlighted hashtags are in the ranking.</p>
<div class="hr-wrap"><table class="hr-table hr-posts"><colgroup><col class="w-posted"><col class="w-account"><col class="w-likes"><col class="w-tags"><col><col class="w-link"></colgroup>
<thead><tr><th>Posted</th><th>Account</th><th class="n">Likes</th><th>Hashtags</th><th>Caption</th><th>Link</th></tr></thead>
<tbody>${postRows}</tbody></table></div><p id="hr-post-nomatch" class="hr-note" hidden>No post matches the filter.</p></section>` : '';
const nav = `<nav class="hr-nav"><a class="hr-logo" href="${SITE_URL}" target="_blank" rel="noopener"><img src="${LOGO_URL}" alt="RecentReborn" height="28"></a><span class="hr-live">Real-time Instagram search</span></nav>`;
// Two-tone headline like the site: black first line, purple second line.
const head = (title, accent, sub) => `${nav}<header class="hr-hero"><span class="hr-pill">Instagram hashtag analysis</span><h1>${title}<em>${accent}</em></h1><p class="hr-sub">${sub}</p></header>`;
const seedHtml = `#${esc(s.hashtag)}`;
const foot = `<footer class="hr-foot"><span>Generated ${esc(s.finishedAt.slice(0, 16).replace('T', ' '))} UTC. About ${fmt(s.estimatedCredits)} search credit(s) used.</span><a href="${SITE_URL}" target="_blank" rel="noopener">Powered by <img src="${LOGO_URL}" alt="RecentReborn" height="18"></a></footer>`;

let body;
let script = '';
let setbar = '';
if (d.outcome === 'failed') {
  body = head('Search failed for', seedHtml, 'No results could be fetched. Failed searches cost no credits. Go back to the form and try again once the problem is fixed.')
    + `<div class="hr-msg bad">${d.errors.map(e => `<p><b>${esc(e.advice)}</b><br><small>${esc(e.message)}</small></p>`).join('')}</div>`;
} else if (d.outcome === 'no_posts') {
  body = head('No recent posts for', seedHtml, `RecentReborn found no recent Instagram ${esc(feedLabel)} for this hashtag. Check the spelling or try a broader hashtag.`)
    + warnings;
} else if (d.outcome === 'no_cohashtags') {
  body = head('No shared hashtags yet for', seedHtml, `${fmt(s.analysedPosts)} posts were analysed, but no other hashtag was used by at least ${fmt(s.minAccounts)} different accounts. Try a larger sample, or lower <code>minAccountsPerHashtag</code> in the Config node.`)
    + cards + warnings + postsPanel;
} else {
  const maxAccounts = Math.max(...d.rows.map(r => r.accounts));
  const maxShare = Math.max(...d.rows.map(r => r.sharePct));
  const rowsHtml = d.rows.map(r => {
    const notes = (r.concentrated ? '<span class="hr-badge w" title="One account made more than half of the uses">mostly one account</span>' : '')
      + (r.containsSearchTerm ? `<span class="hr-badge">contains #${esc(s.hashtag)}</span>` : '');
    return `<tr data-tag="${esc(r.hashtag)}" data-rank="${r.rank}" data-accounts="${r.accounts}" data-posts="${r.posts}" data-share="${r.sharePct}" data-likes="${r.avgLikes ?? ''}" data-ei="${r.engagementIndex ?? ''}">`
      + `<td class="js-only hr-col-pick"><input type="checkbox" class="hr-pick" value="${esc(r.hashtag)}" aria-label="Add #${esc(r.hashtag)} to your set"></td>`
      + `<td class="n rank c-rank">${r.rank}</td>`
      + `<td class="c-tag"><a class="hr-tag" href="${esc(tagUrl(r.hashtag))}" target="_blank" rel="noopener">#${esc(r.hashtag)}</a>${notes ? `<div class="hr-notes">${notes}</div>` : ''}</td>`
      + `<td class="hr-barcell"><div><i style="width:${Math.max(4, Math.round((48 * r.accounts) / maxAccounts))}px"></i><b>${fmt(r.accounts)}</b></div></td>`
      + `<td class="n"><a href="#hr-posts" data-act="posts" data-tag="${esc(r.hashtag)}" title="Show these posts">${fmt(r.posts)}</a></td>`
      + `<td class="hr-barcell c-share"><div class="alt"><i style="width:${Math.max(4, Math.round((48 * r.sharePct) / maxShare))}px"></i><b>${r.sharePct}%</b></div></td>`
      + `<td class="n c-likes">${fmt(r.avgLikes)}</td>`
      + `<td class="n"><span class="hr-ei ${eiClass(r.engagementIndex)}">${r.engagementIndex === null ? 'n/a' : r.engagementIndex.toFixed(2)}</span></td>`
      + `<td class="c-link">${isUrl(r.examplePost) ? `<a href="${esc(r.examplePost)}" target="_blank" rel="noopener" title="Open the most-liked post">Open&nbsp;&#8599;</a>` : ''}</td></tr>`;
  }).join('');

  // Narrow screens show the short label, so the hashtag column keeps its room.
  const th = (label, key, type, cls = '', short = '') => `<th class="${cls}" data-sort="${key}" data-type="${type}" title="Sort by ${label.toLowerCase()}">${short ? `<span class="hr-l">${label}</span><span class="hr-s">${short}</span>` : label}</th>`;
  const table = `<section class="hr-panel"><div class="hr-panel-head">${panelHead('01. Ranking', `Top ${fmt(d.rows.length)} hashtags used with #${esc(s.hashtag)}`)}
<div class="hr-tools js-only">${searchBox('hr-filter', 'Filter hashtags')}
<button type="button" data-act="top">Add top 10 shown</button><button type="button" data-act="csv">Download CSV</button></div></div>
<div class="hr-wrap"><table class="hr-table hr-rank"><thead><tr><th class="js-only hr-col-pick"></th>${th('#', 'rank', 'num', 'n c-rank')}${th('Hashtag', 'tag', 'text', 'c-tag')}${th('Accounts', 'accounts', 'num', '', 'Acc.')}${th('Posts', 'posts', 'num', 'n')}${th('Share', 'share', 'num', 'c-share')}${th('Avg likes', 'likes', 'num', 'n c-likes')}${th('Eng. index', 'ei', 'num', 'n', 'EI')}<th class="c-link">Top post</th></tr></thead>
<tbody>${rowsHtml}</tbody></table></div><p id="hr-nomatch" class="hr-note" hidden>No hashtag matches the filter.</p></section>`;

  const pairsHtml = d.pairs.length
    ? `<table class="hr-table hr-pairs"><thead><tr><th>Pair</th><th class="n">Accounts</th><th class="n">Posts</th></tr></thead><tbody>${d.pairs.map(p => `<tr><td>#${esc(p.pair[0])}<span class="hr-plus">+</span>#${esc(p.pair[1])}</td><td class="n">${fmt(p.accounts)}</td><td class="n">${fmt(p.posts)}</td></tr>`).join('')}</tbody></table>`
    : `<p class="hr-note">No pair of listed hashtags was used by ${fmt(s.minAccounts)} or more accounts.</p>`;

  // Graph: the top hashtags as nodes, pairs between them as edges.
  const gNodes = d.rows.slice(0, graphNodes).map(r => ({ tag: r.hashtag, accounts: r.accounts, posts: r.posts, ei: r.engagementIndex }));
  const inGraph = new Set(gNodes.map(n => n.tag));
  const gEdges = (d.edges || []).filter(e => inGraph.has(e.pair[0]) && inGraph.has(e.pair[1])).map(e => [e.pair[0], e.pair[1], e.accounts]);
  const showGraph = gNodes.length >= 3 && gEdges.length > 0;
  const graphPanel = showGraph ? `<section class="hr-panel js-only">${panelHead('02. Network', 'How the hashtags connect')}
<p class="hr-note">Top ${gNodes.length} hashtags. Size = accounts, lines = used in the same posts (thicker = more accounts). Hover to see connections, click to add to your set.</p>
<div id="hr-graph"></div><div class="hr-legend"><span style="--c:var(--good-fill)">more likes than average</span><span style="--c:var(--mid-fill)">around average</span><span style="--c:var(--lo-fill)">fewer likes</span><span style="--c:var(--na-fill)">no like data</span></div></section>` : '';
  const pairsPanel = `<section class="hr-panel">${panelHead('03. Pairs', 'Often used together')}<p class="hr-note">Pairs from the table that appear in the same posts.</p><div class="hr-wrap" style="margin-top:8px">${pairsHtml}</div></section>`;

  const csv = '﻿' + ['rank,hashtag,accounts,posts,share_pct,avg_likes,engagement_index,mostly_one_account,top_post']
    .concat(d.rows.map(r => [r.rank, r.hashtag, r.accounts, r.posts, r.sharePct, r.avgLikes ?? '', r.engagementIndex ?? '', r.concentrated, r.examplePost].map(csvCell).join(',')))
    .join('\n');
  const preselect = d.rows.slice(0, copyCount).map(r => r.hashtag);

  body = head('Hashtags used with', seedHtml,
    `Based on the ${fmt(s.analysedPosts)} most recent Instagram ${esc(feedLabel)}. Ranked by how many different accounts used each hashtag together with #${esc(s.hashtag)}, so one busy account cannot dominate.`)
    + cards + warnings + table
    + (showGraph ? `<div class="hr-grid">${graphPanel}${pairsPanel}</div>` : pairsPanel)
    + postsPanel
    + `<div class="nojs-only hr-panel">${panelHead('Copy', 'Top hashtags as one line')}<textarea readonly rows="2" style="margin-top:8px">${esc(preselect.map(t => '#' + t).join(' '))}</textarea></div>`
    + `<details><summary>How to read this</summary><ul>
<li><b>Accounts</b>: different accounts that used the hashtag together with #${esc(s.hashtag)}. This is the ranking key.</li>
<li><b>Posts, Share</b>: posts in the sample that contain the hashtag.</li>
<li><b>Avg likes, Eng. index</b>: average likes of those posts, and that average divided by the sample average (${fmt(s.avgLikes)} likes over ${fmt(s.postsWithLikes)} posts with a visible like count). Above 1 means more likes than usual. Needs 2 or more posts with likes.</li>
<li><b>mostly one account</b>: a single account made more than half of the uses, often a brand or bot repeating its tag set.</li>
<li>Hashtags used by fewer than ${fmt(s.minAccounts)} accounts are hidden. The sample is a snapshot of recent activity, not a long-term average.</li></ul></details>`
    + `<details id="hr-raw"><summary>Table as CSV</summary><textarea readonly rows="8">${esc(csv.slice(1))}</textarea></details>`;

  const data = { csv, fileName: `hashtags-${s.hashtag}-${s.finishedAt.slice(0, 10)}.csv`, preselect, graph: { nodes: gNodes, edges: gEdges } };

  // Browser-side behaviour. This function is serialised into the page and runs in the viewer's browser,
  // so it must not use any variable from this Code node.
  function hashtagPage() {
    var app = document.getElementById('hr-app');
    var dataEl = document.getElementById('hr-data');
    if (!app || !dataEl) return;
    var data = JSON.parse(dataEl.textContent);
    app.classList.add('js');
    var q = function (sel) { return app.querySelector(sel); };
    var qa = function (sel, el) { return Array.prototype.slice.call((el || app).querySelectorAll(sel)); };
    var tbody = q('.hr-rank tbody');
    var selected = data.preselect.slice();

    // Your hashtag set
    function renderSet() {
      var box = q('#hr-chips');
      box.textContent = '';
      if (!selected.length) {
        var hint = document.createElement('span');
        hint.className = 'hr-hint';
        hint.textContent = 'Tick hashtags in the table or click them in the graph.';
        box.appendChild(hint);
      }
      selected.forEach(function (tag) {
        var chip = document.createElement('button');
        chip.type = 'button';
        chip.className = 'hr-chip';
        chip.title = 'Remove #' + tag;
        chip.textContent = '#' + tag;
        chip.addEventListener('click', function () { toggle(tag, false); });
        box.appendChild(chip);
      });
      q('#hr-count').textContent = String(selected.length);
      qa('.hr-pick').forEach(function (c) {
        c.checked = selected.indexOf(c.value) >= 0;
        c.closest('tr').classList.toggle('sel', c.checked);
      });
      qa('.hr-node').forEach(function (n) { n.classList.toggle('sel', selected.indexOf(n.getAttribute('data-tag')) >= 0); });
    }
    function toggle(tag, on) {
      var i = selected.indexOf(tag);
      if (on === undefined) on = i < 0;
      if (on && i < 0) selected.push(tag);
      if (!on && i >= 0) selected.splice(i, 1);
      renderSet();
    }
    app.addEventListener('change', function (e) {
      if (e.target.classList.contains('hr-pick')) toggle(e.target.value, e.target.checked);
    });

    // Copy: the clipboard API can be blocked in n8n's sandboxed page, so fall back to execCommand, then a prompt.
    function flash(btn, text) {
      var old = btn.getAttribute('data-label') || btn.textContent;
      btn.setAttribute('data-label', old);
      btn.textContent = text;
      setTimeout(function () { btn.textContent = old; }, 1600);
    }
    function copy(text, btn) {
      if (!text) { flash(btn, 'Nothing selected'); return; }
      var fallback = function () {
        var t = document.createElement('textarea');
        t.value = text;
        t.style.position = 'fixed';
        t.style.opacity = '0';
        document.body.appendChild(t);
        t.select();
        var ok = false;
        try { ok = document.execCommand('copy'); } catch (err) { ok = false; }
        document.body.removeChild(t);
        if (ok) flash(btn, 'Copied');
        else window.prompt('Copy your hashtags:', text);
      };
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(function () { flash(btn, 'Copied'); }, fallback);
      } else fallback();
    }

    function downloadCsv() {
      try {
        var a = document.createElement('a');
        a.href = URL.createObjectURL(new Blob([data.csv], { type: 'text/csv;charset=utf-8' }));
        a.download = data.fileName;
        document.body.appendChild(a);
        a.click();
        setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 1500);
      } catch (err) {
        var raw = q('#hr-raw');
        raw.open = true;
        raw.scrollIntoView({ behavior: 'smooth' });
      }
    }

    app.addEventListener('click', function (e) {
      var btn = e.target.closest('[data-act]');
      if (!btn) return;
      var act = btn.getAttribute('data-act');
      if (act === 'copy') copy(selected.map(function (t) { return '#' + t; }).join(' '), btn);
      if (act === 'clear') { selected = []; renderSet(); }
      if (act === 'csv') downloadCsv();
      if (act === 'posts') { e.preventDefault(); showPostsFor(btn.getAttribute('data-tag')); }
      if (act === 'top') {
        qa('tr', tbody).filter(function (r) { return !r.hidden; }).slice(0, 10).forEach(function (r) {
          if (selected.indexOf(r.dataset.tag) < 0) selected.push(r.dataset.tag);
        });
        renderSet();
      }
    });

    // Sorting: click a column header. Empty values (n/a) always go last.
    qa('.hr-table th[data-sort]').forEach(function (th) {
      th.tabIndex = 0;
      var sort = function () {
        var key = th.getAttribute('data-sort');
        var numeric = th.getAttribute('data-type') === 'num';
        var firstAsc = key === 'rank' || key === 'tag';
        var cur = th.getAttribute('aria-sort');
        var dir = cur ? (cur === 'ascending' ? 'descending' : 'ascending') : (firstAsc ? 'ascending' : 'descending');
        qa('.hr-table th[data-sort]').forEach(function (h) { h.removeAttribute('aria-sort'); });
        th.setAttribute('aria-sort', dir);
        var rows = qa('tr', tbody);
        rows.sort(function (a, b) {
          var x = a.dataset[key], y = b.dataset[key];
          if (numeric && (x === '') !== (y === '')) return x === '' ? 1 : -1;
          var c = numeric ? Number(x) - Number(y) : String(x).localeCompare(String(y));
          if (c === 0) return Number(a.dataset.rank) - Number(b.dataset.rank);
          return dir === 'ascending' ? c : -c;
        });
        rows.forEach(function (r) { tbody.appendChild(r); });
      };
      th.addEventListener('click', sort);
      th.addEventListener('keydown', function (e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); sort(); } });
    });

    // Filter
    var filter = q('#hr-filter');
    filter.addEventListener('input', function () {
      var v = filter.value.trim().toLowerCase().replace(/^#+/, '');
      var shown = 0;
      qa('tr', tbody).forEach(function (r) {
        r.hidden = !!v && r.dataset.tag.indexOf(v) < 0;
        if (!r.hidden) shown++;
      });
      q('#hr-nomatch').hidden = shown > 0;
    });

    // Network graph: a small force layout computed once, then drawn as SVG.
    function drawGraph() {
      var host = q('#hr-graph');
      if (!host || !data.graph.nodes.length) return;
      var NS = 'http://www.w3.org/2000/svg', W = 760, H = 470;
      var count = data.graph.nodes.length;
      var nodes = data.graph.nodes.map(function (n, i) {
        var a = (2 * Math.PI * i) / count;
        return { tag: n.tag, accounts: n.accounts, posts: n.posts, ei: n.ei, x: W / 2 + 220 * Math.cos(a), y: H / 2 + 150 * Math.sin(a), vx: 0, vy: 0 };
      });
      var byTag = {};
      nodes.forEach(function (n) { byTag[n.tag] = n; });
      var links = data.graph.edges.map(function (e) { return { s: byTag[e[0]], t: byTag[e[1]], w: e[2] }; });
      var maxA = Math.max.apply(null, nodes.map(function (n) { return n.accounts; }));
      var maxW = Math.max.apply(null, links.map(function (l) { return l.w; }).concat([1]));
      nodes.forEach(function (n) { n.r = 7 + 15 * Math.sqrt(n.accounts / maxA); });

      for (var it = 0; it < 450; it++) {
        var cool = 1 - it / 450;
        for (var i = 0; i < count; i++) {
          for (var j = i + 1; j < count; j++) {
            var a = nodes[i], b = nodes[j];
            var dx = b.x - a.x, dy = b.y - a.y, d2 = dx * dx + dy * dy || 0.01, d = Math.sqrt(d2);
            var room = a.r + b.r + 44; // space for labels
            var f = 2600 / d2 + (d < room ? (room - d) * 0.3 : 0);
            a.vx -= (dx / d) * f; a.vy -= (dy / d) * f;
            b.vx += (dx / d) * f; b.vy += (dy / d) * f;
          }
        }
        links.forEach(function (l) {
          var dx = l.t.x - l.s.x, dy = l.t.y - l.s.y, d = Math.sqrt(dx * dx + dy * dy) || 0.01;
          var f = (d - (80 + 70 * (1 - l.w / maxW))) * 0.03 * (0.4 + l.w / maxW);
          l.s.vx += (dx / d) * f; l.s.vy += (dy / d) * f;
          l.t.vx -= (dx / d) * f; l.t.vy -= (dy / d) * f;
        });
        nodes.forEach(function (n) {
          n.vx += (W / 2 - n.x) * 0.004;
          n.vy += (H / 2 - n.y) * 0.007;
          var sp = Math.sqrt(n.vx * n.vx + n.vy * n.vy), max = 1 + 14 * cool;
          if (sp > max) { n.vx *= max / sp; n.vy *= max / sp; }
          n.x = Math.min(W - n.r - 50, Math.max(n.r + 50, n.x + n.vx));
          n.y = Math.min(H - n.r - 22, Math.max(n.r + 8, n.y + n.vy));
          n.vx *= 0.55; n.vy *= 0.55;
        });
      }

      // Scale and centre the layout so it fills the drawing area (labels need about 3.2 px per character).
      var half = function (n) { return Math.max(n.r, (n.tag.length + 1) * 3.2); };
      var minX = Math.min.apply(null, nodes.map(function (n) { return n.x - half(n); }));
      var maxX = Math.max.apply(null, nodes.map(function (n) { return n.x + half(n); }));
      var minY = Math.min.apply(null, nodes.map(function (n) { return n.y - n.r; }));
      var maxY = Math.max.apply(null, nodes.map(function (n) { return n.y + n.r + 16; }));
      var scale = Math.min((W - 24) / (maxX - minX || 1), (H - 24) / (maxY - minY || 1), 2.2);
      nodes.forEach(function (n) {
        n.x = W / 2 + (n.x - (minX + maxX) / 2) * scale;
        n.y = H / 2 + (n.y - (minY + maxY) / 2) * scale;
      });

      var el = function (name, attrs, parent) {
        var x = document.createElementNS(NS, name);
        Object.keys(attrs).forEach(function (k) { x.setAttribute(k, attrs[k]); });
        if (parent) parent.appendChild(x);
        return x;
      };
      var svg = el('svg', { viewBox: '0 0 ' + W + ' ' + H, role: 'img', 'aria-label': 'Network of co-used hashtags' });
      var neighbours = {};
      nodes.forEach(function (n) { neighbours[n.tag] = [n.tag]; });
      links.forEach(function (l) {
        neighbours[l.s.tag].push(l.t.tag);
        neighbours[l.t.tag].push(l.s.tag);
        l.el = el('line', { class: 'hr-link', x1: l.s.x, y1: l.s.y, x2: l.t.x, y2: l.t.y, 'stroke-width': 1 + (3.5 * l.w) / maxW }, svg);
      });
      var focus = function (tag) {
        svg.classList.toggle('focus', !!tag);
        nodes.forEach(function (n) { n.el.classList.toggle('on', !!tag && neighbours[tag].indexOf(n.tag) >= 0); });
        links.forEach(function (l) { l.el.classList.toggle('on', !!tag && (l.s.tag === tag || l.t.tag === tag)); });
      };
      nodes.forEach(function (n) {
        var cls = n.ei === null ? 'na' : n.ei >= 1.2 ? 'hi' : n.ei <= 0.8 ? 'lo' : 'mid';
        var g = el('g', { class: 'hr-node ' + cls, 'data-tag': n.tag, tabindex: '0', role: 'button', 'aria-label': 'Add or remove #' + n.tag }, svg);
        el('title', {}, g).textContent = '#' + n.tag + ': ' + n.accounts + ' accounts, ' + n.posts + ' posts' + (n.ei === null ? '' : ', engagement index ' + n.ei.toFixed(2));
        el('circle', { cx: n.x, cy: n.y, r: n.r }, g);
        el('text', { x: n.x, y: n.y + n.r + 13, 'text-anchor': 'middle' }, g).textContent = '#' + n.tag;
        g.addEventListener('mouseenter', function () { focus(n.tag); });
        g.addEventListener('mouseleave', function () { focus(null); });
        g.addEventListener('focus', function () { focus(n.tag); });
        g.addEventListener('blur', function () { focus(null); });
        g.addEventListener('click', function () { toggle(n.tag); });
        g.addEventListener('keydown', function (e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggle(n.tag); } });
        n.el = g;
      });
      host.appendChild(svg);
    }

    // Post list: filter by #hashtag (prefix, or exact after clicking a count), account or text; flip the order.
    var ptbody = q('.hr-posts tbody');
    var pfilter = q('#hr-post-filter');
    var porder = q('#hr-post-order');
    var exactTag = null;
    function applyPosts() {
      if (!ptbody) return;
      var v = pfilter.value.trim().toLowerCase();
      var tag = v.charAt(0) === '#' ? v.slice(1) : null;
      var rows = qa('tr', ptbody), shown = 0;
      rows.forEach(function (r) {
        var ok = !v || (tag !== null
          ? r.dataset.tags.indexOf(' ' + tag + (exactTag === tag ? ' ' : '')) >= 0
          : (r.dataset.tags + ' ' + r.dataset.text).indexOf(v) >= 0);
        r.hidden = !ok;
        if (ok) shown++;
      });
      q('#hr-post-count').textContent = v ? shown + ' of ' + rows.length : String(rows.length);
      q('#hr-post-nomatch').hidden = shown > 0;
    }
    function orderPosts() {
      var asc = porder.value === 'asc';
      qa('tr', ptbody).sort(function (a, b) {
        var x = a.dataset.time === '' ? null : Number(a.dataset.time), y = b.dataset.time === '' ? null : Number(b.dataset.time);
        if (x === null || y === null) return x === y ? 0 : x === null ? 1 : -1; // unknown dates last
        return asc ? x - y : y - x;
      }).forEach(function (r) { ptbody.appendChild(r); });
    }
    function showPostsFor(tag) {
      if (!ptbody) return;
      exactTag = tag;
      pfilter.value = '#' + tag;
      applyPosts();
      q('#hr-posts').scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
    if (ptbody) {
      pfilter.addEventListener('input', function () { exactTag = null; applyPosts(); });
      porder.addEventListener('change', orderPosts);
      // Show post times in the viewer's own time zone (the UTC time stays in the tooltip).
      qa('time', ptbody).forEach(function (t) {
        var dt = new Date(t.getAttribute('datetime'));
        if (!isNaN(dt)) { t.title = t.textContent; t.textContent = dt.toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }); }
      });
    }

    drawGraph();
    renderSet();
  }

  setbar = `<div class="hr-setbar js-only"><div class="hr-setbar-in"><strong>Your set (<span id="hr-count">0</span>)</strong>
<div id="hr-chips" class="hr-chips"></div><button type="button" class="primary" data-act="copy">Copy hashtags</button><button type="button" data-act="clear">Clear</button></div></div>`;
  script = `<script type="application/json" id="hr-data">${safeJson(data)}</script>\n<script>(${hashtagPage.toString()})();</script>`;
}

const html = `${fonts}<style>${css}</style>\n<div class="hr-app" id="hr-app">${body}${foot}${setbar}</div>\n${script}`;

return [{ json: { fromForm: d.fromForm, outcome: d.outcome, summary: s, html } }];
